SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">DNA\'NIN YARI KORUNUMLU EŞLENMESİ VE GÖREVLİ 3 TEMEL ENZİM</text>\n\n  <!-- Sol Kutu: Yarı Korunumlu Eşlenme ve Orijin -->\n  <rect x="16" y="42" width="318" height="202" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="175" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">MESELSON - STAHL (YARI KORUNUMLU)</text>\n  <line x1="30" y1="72" x2="320" y2="72" stroke="#93c5fd" stroke-width="1.5"/>\n  <!-- Ata DNA -->\n  <line x1="45" y1="92" x2="45" y2="142" stroke="#1d4ed8" stroke-width="4"/>\n  <line x1="57" y1="92" x2="57" y2="142" stroke="#1d4ed8" stroke-width="4"/>\n  <text x="51" y="158" text-anchor="middle" font-size="9.5" font-weight="bold" fill="#1e3a8a">Ata DNA</text>\n  <line x1="72" y1="117" x2="102" y2="117" stroke="#475569" stroke-width="2"/>\n  <polygon points="106,117 98,113 98,121" fill="#475569"/>\n  <!-- 2 Yeni DNA -->\n  <line x1="122" y1="86" x2="122" y2="120" stroke="#1d4ed8" stroke-width="4"/>\n  <line x1="132" y1="86" x2="132" y2="120" stroke="#dc2626" stroke-width="4"/>\n  <line x1="122" y1="128" x2="122" y2="162" stroke="#1d4ed8" stroke-width="4"/>\n  <line x1="132" y1="128" x2="132" y2="162" stroke="#dc2626" stroke-width="4"/>\n  <text x="232" y="102" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e3a8a">1 Eski (Kalıp) Zincir</text>\n  <text x="232" y="120" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#dc2626">+ 1 Yeni Zincir</text>\n  <text x="232" y="140" text-anchor="middle" font-size="10" fill="#334155">(¹⁵N ve ¹⁴N E. coli deneyi)</text>\n\n  <rect x="28" y="172" width="294" height="60" rx="6" fill="#dbeafe" stroke="#3b82f6"/>\n  <text x="175" y="190" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Replikasyon Orijini Sayısı:</text>\n  <text x="175" y="207" text-anchor="middle" font-size="10.5" fill="#1e3a8a">• Prokaryot (Halkasal DNA): TEK replikasyon orijini</text>\n  <text x="175" y="223" text-anchor="middle" font-size="10.5" fill="#1e3a8a">• Ökaryot (Doğrusal DNA): ÇOK SAYIDA orijin</text>\n\n  <!-- Sağ Kutu: Görevli 3 Enzim -->\n  <rect x="348" y="42" width="336" height="202" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="516" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">REPLİKASYONDA GÖREVLİ ENZİMLER</text>\n  <line x1="362" y1="72" x2="670" y2="72" stroke="#86efac" stroke-width="1.5"/>\n\n  <rect x="360" y="82" width="312" height="46" rx="6" fill="#dcfce7" stroke="#22c55e"/>\n  <text x="370" y="100" font-size="11" font-weight="bold" fill="#14532d">1. Helikaz:</text>\n  <text x="370" y="116" font-size="10" fill="#166534">Zayıf hidrojen bağlarını koparıp sarmalı açar (ATP harcanmaz).</text>\n\n  <rect x="360" y="135" width="312" height="46" rx="6" fill="#dcfce7" stroke="#22c55e"/>\n  <text x="370" y="153" font-size="11" font-weight="bold" fill="#14532d">2. DNA Polimeraz:</text>\n  <text x="370" y="169" font-size="10" fill="#166534">Kalıp zincirin karşısına uygun nükleotitleri ekler, yeni zinciri kurar.</text>\n\n  <rect x="360" y="188" width="312" height="46" rx="6" fill="#dcfce7" stroke="#22c55e"/>\n  <text x="370" y="206" font-size="11" font-weight="bold" fill="#14532d">3. DNA Ligaz:</text>\n  <text x="370" y="222" font-size="10" fill="#166534">DNA parçacıklarını fosfodiester bağıyla birleştirir (ATP harcar).</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PROF. DR. AZİZ SANCAR VE DNA ONARIM MEKANİZMASI</text>\n\n  <!-- Sol Kutu: Bilimsel Keşifler -->\n  <rect x="18" y="45" width="340" height="198" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="188" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">2015 NOBEL KİMYA ÖDÜLÜ ÇALIŞMALARI</text>\n  <line x1="32" y1="76" x2="344" y2="76" stroke="#fde047" stroke-width="1.5"/>\n  <text x="32" y="100" font-size="11" font-weight="bold" fill="#713f12">• Nükleotit Kesip Çıkarma Onarımı:</text>\n  <text x="40" y="118" font-size="10.5" fill="#854d0e">UV (morötesi) ışınları ve kanserojen maddelerle</text>\n  <text x="40" y="134" font-size="10.5" fill="#854d0e">hasar gören DNA\'nın hücreler tarafından nasıl</text>\n  <text x="40" y="150" font-size="10.5" fill="#854d0e">onarıldığını ve genetik bilginin korunduğunu haritaladı.</text>\n  <text x="32" y="176" font-size="11" font-weight="bold" fill="#713f12">• Biyolojik Saat (Sirkadiyen Ritim):</text>\n  <text x="40" y="194" font-size="10.5" fill="#854d0e">Canlılardaki biyolojik saat genleri ve kanser</text>\n  <text x="40" y="210" font-size="10.5" fill="#854d0e">kemoterapisinin zamanlaması üzerine öncü çalışmalar yaptı.</text>\n\n  <!-- Sağ Kutu: Bilim İnsanı Kimliği ve Vatanseverliği -->\n  <rect x="374" y="45" width="308" height="198" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="528" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be123c">ÖRNEK BİLİM İNSANI KİMLİĞİ</text>\n  <line x1="388" y1="76" x2="668" y2="76" stroke="#fda4af" stroke-width="1.5"/>\n  <text x="390" y="102" font-size="11" fill="#881337">• Mardin\'in Savur ilçesinde doğdu; azim ve</text>\n  <text x="398" y="118" font-size="11" fill="#881337">kararlılıkla dünya çapında başarılara ulaştı.</text>\n  <text x="390" y="144" font-size="11" fill="#881337">• Günde 18 saate varan disiplinli çalışma</text>\n  <text x="398" y="160" font-size="11" fill="#881337">ahlakı, sabır ve bilimsel merak duygusu.</text>\n  <rect x="390" y="176" width="276" height="52" rx="6" fill="#ffe4e6" stroke="#f43f5e"/>\n  <text x="528" y="196" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">Vatanseverlik ve Cumhuriyet Bilinci:</text>\n  <text x="528" y="214" text-anchor="middle" font-size="10.5" fill="#881337">Nobel Ödülü madalyasını ve sertifikasını</text>\n  <text x="528" y="226" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#be123c">Anıtkabir\'e armağan etmiştir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
